      const evaluations = runEvaluations({
        outputs: ['hello'],
        references: ['hello'],
        metrics: [customMetric]
      });
      const report = generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        thresholds: { custom_metric: 0.7 }
      });

      expect(report.passed).toBe(true);
      expect(report.thresholds).toEqual([
        { metric: 'custom_metric', min: 0.7, score: 0.75, passed: true }
      ]);
    });

    it('leaves the report unchanged when no thresholds are supplied', () => {
      const evaluations = runEvaluations({
        outputs: ['hello'],
        references: ['hello']
      });
      const report = generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json'
      });

      expect(report.passed).toBeUndefined();
      expect(report.thresholds).toBeUndefined();
    });

    it('renders a Thresholds section in the markdown report', () => {
      const evaluations = runEvaluations({
        outputs: ['hello'],
        references: ['hello']
      });
      const report = generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        thresholds: { exact_match: 0.9 }
      });

      const dir = createTempDir();
      const markdownPath = writeReport({
        report,
        format: 'markdown',
        reportPath: path.join(dir, 'report.md')
      });
      const markdown = fs.readFileSync(markdownPath, 'utf8');

      expect(markdown).toContain('## Thresholds');
      expect(markdown).toContain('exact_match');
      expect(markdown).toContain('PASS');
    });
  });
});

